//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::nat::check_result_bits`; the
//! native twin is `benches/native/Bench/NatCheckResultBits.lean`.
//! NOT COMPARABLE: the size test of nat::pow and nat::shiftl on a big result; native has no
//! counterpart (it refuses exponents and shifts of 2^32 or more instead, LB-11 and LB-12)

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::nat;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match nat::check_result_bits::<ColdBig>(u128::from(x >> 28) + 64) {
                Ok(b) => b,
                Err(p) => end(p),
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
